#!/usr/bin/env bun
/**
 * Live end-to-end check of the hub's grant and revoke path against one POC.
 * Uses three throwaway accounts on addresses with no mailbox and deletes them
 * afterwards. Needs application-default credentials with Firebase Auth admin
 * and Firestore access to `platform` (the platform owner, never CI).
 *
 *   FIREBASE_PROJECT_ID=<project> NEXT_PUBLIC_FIREBASE_API_KEY=<key> \
 *   HUB_URL=https://poc.nicholaswood.com.au APP_URL=https://<id>.poc.nicholaswood.com.au APP_ID=<id> \
 *   bun run skills/poc-deploy/tools/live-e2e.ts
 *
 * Proves: the hub refuses a non-admin; a grant through the hub API admits the
 * member to the POC; an unallocated user is refused; a revoke through the hub
 * API makes the POC refuse both the member's existing session and a new one.
 */
import { getAuth } from "firebase-admin/auth";
import { adminApp, appDb } from "../../../packages/poc-auth/src/firebase";

const env = (k: string) => {
  const v = process.env[k];
  if (!v) throw new Error(`${k} is required`);
  return v.replace(/\/$/, "");
};
const HUB = env("HUB_URL"), APP = env("APP_URL"), APP_ID = env("APP_ID"), KEY = env("NEXT_PUBLIC_FIREBASE_API_KEY");
env("FIREBASE_PROJECT_ID");
const stamp = Date.now().toString(36);
const who = (r: string) => `probe-${r}-${stamp}@probe.poc.nicholaswood.com.au`;
const admin = who("admin"), member = who("member"), outsider = who("outsider");

const auth = getAuth(adminApp());
const db = appDb("platform");
let failed = 0;
const check = (name: string, ok: boolean, detail = "") => {
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${name}${detail ? `  [${detail}]` : ""}`);
};

async function idToken(email: string, referer: string) {
  const u = await auth.getUserByEmail(email);
  const ct = await auth.createCustomToken(u.uid);
  const r = await fetch(`https://identitytoolkit.googleapis.com/v1/accounts:signInWithCustomToken?key=${KEY}`, {
    method: "POST",
    headers: { "Content-Type": "application/json", Referer: `${referer}/` },
    body: JSON.stringify({ token: ct, returnSecureToken: true }),
  });
  const b = (await r.json()) as { idToken?: string; error?: { message?: string } };
  if (!b.idToken) throw new Error(`custom token exchange failed: ${b.error?.message ?? r.status}`);
  return b.idToken;
}
const session = (base: string, token: string) =>
  fetch(`${base}/api/auth/session`, { method: "POST", headers: { "Content-Type": "application/json", Origin: base }, body: JSON.stringify({ idToken: token }) });
const cookieOf = (r: Response) => (r.headers.get("set-cookie") ?? "").split(";")[0];
const allocation = (method: "POST" | "DELETE", cookie: string, body: object) =>
  fetch(`${HUB}/api/admin/allocations`, { method, headers: { "Content-Type": "application/json", Origin: HUB, Cookie: cookie }, body: JSON.stringify(body) });

try {
  for (const e of [admin, outsider]) await auth.createUser({ email: e, emailVerified: true });
  const at = new Date().toISOString();
  await db.collection("users").doc(admin).set({ email: admin, platformAdmin: true, pocs: {}, updatedAt: at, updatedBy: "live-e2e" });
  await db.collection("users").doc(outsider).set({ email: outsider, platformAdmin: false, pocs: {}, updatedAt: at, updatedBy: "live-e2e" });

  console.log(`# Hub: ${HUB}`);
  const os = await session(HUB, await idToken(outsider, HUB));
  const oc = cookieOf(os);
  const og = await fetch(`${HUB}/api/admin/allocations`, { headers: { Cookie: oc } });
  check("non-admin cannot read the allocation grid", og.status === 403 || og.status === 401, String(og.status));
  const ogr = await allocation("POST", oc, { email: outsider, pocId: APP_ID, role: "admin" });
  check("non-admin cannot grant themselves a POC", ogr.status === 403 || ogr.status === 401, String(ogr.status));

  const as = await session(HUB, await idToken(admin, HUB));
  const ac = cookieOf(as);
  check("platform admin signs in to the hub", as.status === 200 && ac.startsWith("__session="), String(as.status));
  const bad = await allocation("POST", ac, { email: member, pocId: "notregistered", role: "member" });
  check("grant of an unregistered POC id is refused", bad.status >= 400 && bad.status < 500, String(bad.status));
  const g = await allocation("POST", ac, { email: member, pocId: APP_ID, role: "member" });
  check(`grant ${APP_ID} member through the hub API`, g.status === 200, `${g.status} ${(await g.text()).slice(0, 120)}`);
  const mu = await auth.getUserByEmail(member).catch(() => null);
  check(`claim poc_${APP_ID} = member set by the hub`, mu?.customClaims?.[`poc_${APP_ID}`] === "member", JSON.stringify(mu?.customClaims ?? null));

  console.log(`\n# POC: ${APP}`);
  const xo = await session(APP, await idToken(outsider, APP));
  check("unallocated user refused, no cookie", xo.status === 403 && !xo.headers.get("set-cookie"), String(xo.status));
  const ms = await session(APP, await idToken(member, APP));
  const mc = cookieOf(ms);
  check("allocated member gets a session", ms.status === 200 && mc.startsWith("__session="), String(ms.status));
  const page = await fetch(`${APP}/`, { headers: { Cookie: mc }, redirect: "manual" });
  check("member opens the page", page.status === 200, String(page.status));
  const adm = await fetch(`${APP}/admin`, { headers: { Cookie: mc }, redirect: "manual" });
  check("member refused the POC admin window", adm.status === 403, String(adm.status));

  console.log("\n# Revoke");
  const rv = await allocation("DELETE", ac, { email: member, pocId: APP_ID });
  check("revoke through the hub API", rv.status === 200, String(rv.status));
  const mu2 = await auth.getUserByEmail(member);
  check("claim removed", !(`poc_${APP_ID}` in (mu2.customClaims ?? {})), JSON.stringify(mu2.customClaims ?? null));
  const stale = await fetch(`${APP}/`, { headers: { Cookie: mc }, redirect: "manual" });
  check("existing session refused after revoke", stale.status !== 200, String(stale.status));
  const again = await session(APP, await idToken(member, APP));
  check("new session refused after revoke", again.status === 403, String(again.status));
} catch (e) {
  failed++;
  console.log(`FAIL  exception: ${(e as Error).message}`);
} finally {
  for (const e of [admin, member, outsider]) {
    const u = await auth.getUserByEmail(e).catch(() => null);
    if (u) {
      await db.collection("pocs").doc(APP_ID).firestore.terminate().catch(() => undefined);
      await auth.deleteUser(u.uid).catch(() => undefined);
    }
  }
  const db2 = appDb("platform");
  for (const e of [admin, member, outsider]) await db2.collection("users").doc(e).delete().catch(() => undefined);
  console.log("\nprobe accounts and their user records deleted");
}
console.log(failed ? `${failed} FAILED` : "ALL PASS");
process.exit(failed ? 1 : 0);

