/** Completes the email link, exchanges the ID token for the __session cookie, then drops the Firebase client session. */
export default function Callback() {
  const [state, setState] = useState<{ title: string; detail: string; done: boolean }>({ title: "Signing you in", detail: "", done: false });
  const fail = (title: string, detail: string) => setState({ title, detail, done: true });

  useEffect(() => {
    (async () => {
      const href = window.location.href;
      if (!isSignInWithEmailLink(auth, href)) return fail("This sign-in link is not valid", "Request a new link and open it in the same browser.");
      const email = window.localStorage.getItem("emailForSignIn") ?? window.prompt("Confirm your email") ?? "";
      try {
        const cred = await signInWithEmailLink(auth, email, href);
        const res = await fetch("/api/auth/session", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ idToken: await cred.user.getIdToken() }),
        });
        await signOut(auth);
        window.localStorage.removeItem("emailForSignIn");
        if (res.status === 403) return fail("You do not have access here", "$4");
        if (!res.ok) return fail("Sign-in failed", "Please request a new link and try again.");
        const redirect = new URLSearchParams(window.location.search).get("redirect") ?? "/";
        window.location.replace(redirect.startsWith("/") && !redirect.startsWith("//") ? redirect : "/");
      } catch {
        fail("This link has expired or was already used", "Request a new one.");
      }
    })();
  }, []);

  return (
    <main className="auth-shell">
      <div className="auth-card sent">
        {!state.done && <div className="spinner" />}
        <h1>{state.done ? state.title : $3_EXPR}</h1>
        <p className="hint">{state.done ? state.detail : "Signing you in..."}</p>
        {state.done && (
          <p>
            <a href="/sign-in">Back to sign-in</a>
          </p>
        )}
      </div>
    </main>
  );
}
